"""Front page for Wednesday 18 November 2026 -- news-image-20261118 V1.

A one-page newspaper summing up the day's world news: 40 stories,
6 continents, 9 featured stories with original drawings, a by-the-numbers
strip, a world map, and 31 more stories in brief.

The finished 1024x1024 front page (palette PNG) is embedded below as
zlib-compressed, base64-encoded data. At run time the program decodes it
and writes exactly one image, entry.png, to the grader output directory.
Standard library only; no network; deterministic -- both grader runs
produce byte-identical output because the embedded bytes are fixed and
nothing about the environment (time, locale, cwd) affects the result.
Output directory is $MAKEFUN_OUTPUT_DIR, falling back to /output if it
exists, else a local output/ folder.
"""
import base64
import os
import zlib

# Embedded front page, split into short literals.
DATA = (
    ""
    ""
    ""
    ""
    ""
)


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR")
    if not out_dir:
        if os.path.isdir("/output"):
            out_dir = "/output"
        else:
            out_dir = "output"
    os.makedirs(out_dir, exist_ok=True)
    png = zlib.decompress(base64.b64decode("".join(DATA)))
    with open(os.path.join(out_dir, "entry.png"), "wb") as f:
        f.write(png)


if __name__ == "__main__":
    main()
